4	// `Context` wraps `AsyncEngineContext` for PyO3 — exposes cancellation,
5	// trace identity, and span access for engine observability.
6	//
7	// Engine code reaches the observability surface through the
8	// `dynamo.common.backend.telemetry` facade, which is itself a thin wrapper
9	// over [`Context::current_span`] / [`Context::start_span`]. Both return a
10	// unified [`SpanProxy`] handle whose `set_attribute` / `add_event` /
11	// `set_status` operations mirror the OTel `Span` API.
12	
13	use dynamo_backend_common::FirstTokenNotifier;
14	use dynamo_runtime::logging::DistributedTraceContext;
15	pub use dynamo_runtime::pipeline::AsyncEngineContext;
16	use dynamo_runtime::pipeline::context::Controller;
17	use opentelemetry::global::BoxedSpan;
18	use opentelemetry::trace::{Span as OtelSpan, Status, TraceContextExt, Tracer};
19	use opentelemetry::{KeyValue, global};
20	use pyo3::prelude::*;
21	use pyo3::types::{PyBool, PyDict, PyFloat, PyInt, PyList, PyString};
22	use std::collections::{BTreeMap, HashMap};
23	use std::sync::{Arc, Mutex, MutexGuard, OnceLock};
24	use tracing_opentelemetry::OpenTelemetrySpanExt;
