26	/// Process-wide guard: once-per-process WARN when telemetry calls hit a
27	/// parent `engine.generate` span that has no OTel context (i.e., the
28	/// `tracing-opentelemetry` layer isn't installed).
29	/// One log line is enough to surface the configuration issue; rate-limiting
30	/// to once avoids flooding logs in high-QPS workers.
31	///
32	/// Visibility level is WARN because telemetry calls silently no-oping is a
33	/// real operator-relevant misconfiguration — if the engine is recording
34	/// attributes and getting nothing, the operator needs to see it at default
35	/// log levels, not just when debug is enabled.
36	static BRIDGE_MISSING_WARNED: OnceLock<()> = OnceLock::new();
37	
38	fn warn_bridge_missing_once(method: &str) {
39	    if BRIDGE_MISSING_WARNED.set(()).is_ok() {
40	        tracing::warn!(
41	            method,
42	            "telemetry call is a no-op: OTel bridge layer not installed \
43	             (enable OTEL_EXPORT_ENABLED=1, DYN_LOGGING_CONSOLE_FORMAT=jsonl, \
44	             or the legacy DYN_LOGGING_JSONL=1 switch). \
45	             Engine telemetry attributes / events / child spans are NOT \
46	             being recorded. Further no-ops in this process are silent."
47	        );
48	    }
49	}
