51	/// Per-request handle exposed to Python engine code. Owns cancellation
52	/// (via `AsyncEngineContext`), trace identity (via `DistributedTraceContext`),
53	/// the disagg first-token signal, and the captured `engine.generate` span.
54	///
55	/// The span is private — engine code reaches it via [`Context::current_span`]
56	/// (the auto-span proxy) or [`Context::start_span`] (a child span). The
57	/// facade in `dynamo.common.backend.telemetry` is a one-line wrapper around
58	/// those methods.
59	#[derive(Clone)]
60	#[pyclass]
61	pub struct Context {
62	    inner: Arc<dyn AsyncEngineContext>,
63	    trace_context: Option<DistributedTraceContext>,
64	    first_token: Option<FirstTokenNotifier>,
65	    metadata: Arc<Mutex<BTreeMap<String, String>>>,
66	    /// Captured `engine.generate` span. `None` for Python-instantiated test
67	    /// contexts (where no parent span was plumbed in) — `current_span` /
68	    /// `start_span` return a no-op `SpanProxy` in that case.
69	    span: Option<tracing::Span>,
70	}
71	
72	#[derive(Clone)]
73	#[pyclass]
74	pub struct ContextMetadata {
75	    inner: Arc<Mutex<BTreeMap<String, String>>>,
76	}
77	
78	impl ContextMetadata {
79	    fn lock_map(&self) -> MutexGuard<'_, BTreeMap<String, String>> {
80	        self.inner
81	            .lock()
82	            .unwrap_or_else(|poisoned| poisoned.into_inner())
83	    }
84	}
85	
86	#[pymethods]
87	impl ContextMetadata {
88	    fn __getitem__(&self, key: &str) -> PyResult<String> {
89	        self.lock_map()
90	            .get(key)
91	            .cloned()
92	            .ok_or_else(|| PyErr::new::<pyo3::exceptions::PyKeyError, _>(key.to_string()))
93	    }
94	
95	    fn __setitem__(&self, key: String, value: String) {
96	        self.lock_map().insert(key, value);
97	    }
98	
99	    fn __delitem__(&self, key: &str) -> PyResult<()> {
100	        self.lock_map()
101	            .remove(key)
102	            .map(|_| ())
103	            .ok_or_else(|| PyErr::new::<pyo3::exceptions::PyKeyError, _>(key.to_string()))
104	    }
105	
106	    fn __len__(&self) -> usize {
107	        self.lock_map().len()
108	    }
109	
110	    fn __contains__(&self, key: &str) -> bool {
111	        self.lock_map().contains_key(key)
112	    }
113	
114	    fn __iter__<'a>(&self, py: Python<'a>) -> PyResult<Bound<'a, PyAny>> {
115	        let keys = self.lock_map().keys().cloned().collect::<Vec<_>>();
116	        PyList::new(py, keys)?.call_method0("__iter__")
117	    }
118	
119	    #[pyo3(signature = (key, default=None))]
120	    fn get(&self, key: &str, default: Option<String>) -> Option<String> {
121	        self.lock_map().get(key).cloned().or(default)
122	    }
123	
124	    #[pyo3(signature = (key, default = None::<Option<String>>))]
125	    fn pop(&self, key: &str, default: Option<Option<String>>) -> PyResult<Option<String>> {
126	        let mut guard = self.lock_map();
127	        match guard.remove(key) {
128	            Some(value) => Ok(Some(value)),
129	            None if default.is_some() => Ok(default.flatten()),
130	            None => Err(PyErr::new::<pyo3::exceptions::PyKeyError, _>(
131	                key.to_string(),
132	            )),
133	        }
134	    }
135	
136	    fn keys<'a>(&self, py: Python<'a>) -> PyResult<Bound<'a, PyList>> {
137	        let keys = self.lock_map().keys().cloned().collect::<Vec<_>>();
138	        PyList::new(py, keys)
139	    }
140	
141	    fn values<'a>(&self, py: Python<'a>) -> PyResult<Bound<'a, PyList>> {
142	        let values = self.lock_map().values().cloned().collect::<Vec<_>>();
143	        PyList::new(py, values)
144	    }
145	
146	    fn items<'a>(&self, py: Python<'a>) -> PyResult<Bound<'a, PyList>> {
147	        let items = self
148	            .lock_map()
149	            .iter()
150	            .map(|(k, v)| (k.clone(), v.clone()))
151	            .collect::<Vec<_>>();
152	        PyList::new(py, items)
153	    }
154	
155	    fn clear(&self) {
156	        self.lock_map().clear();
157	    }
158	
159	    fn copy<'a>(&self, py: Python<'a>) -> PyResult<Bound<'a, PyDict>> {
160	        let snapshot = self.lock_map().clone();
161	        let dict = PyDict::new(py);
162	        for (key, value) in snapshot {
163	            dict.set_item(key, value)?;
164	        }
165	        Ok(dict)
166	    }
167	
168	    fn __repr__(&self) -> String {
169	        format!("{:?}", self.lock_map().clone())
170	    }
171	}
