173	impl Context {
174	    pub fn new(
175	        inner: Arc<dyn AsyncEngineContext>,
176	        trace_context: Option<DistributedTraceContext>,
177	        first_token: Option<FirstTokenNotifier>,
178	        metadata: BTreeMap<String, String>,
179	    ) -> Self {
180	        Self {
181	            inner,
182	            trace_context,
183	            first_token,
184	            metadata: Arc::new(Mutex::new(metadata)),
185	            span: None,
186	        }
187	    }
188	
189	    /// Attach the `engine.generate` span. Called by `PyLLMEngine::generate`
190	    /// after capturing `Span::current()` outside the spawn_blocking boundary.
191	    /// See `lib/bindings/python/rust/backend.rs` for the invariant.
192	    pub fn with_span(mut self, span: tracing::Span) -> Self {
193	        self.span = Some(span);
194	        self
195	    }
196	
197	    pub fn trace_context(&self) -> Option<&DistributedTraceContext> {
198	        self.trace_context.as_ref()
199	    }
200	
201	    pub fn inner(&self) -> Arc<dyn AsyncEngineContext> {
202	        self.inner.clone()
203	    }
204	
205	    pub fn metadata_snapshot(&self) -> BTreeMap<String, String> {
206	        self.metadata
207	            .lock()
208	            .unwrap_or_else(|poisoned| poisoned.into_inner())
209	            .clone()
210	    }
211	
212	    pub(crate) fn bind_first_token_source(
213	        &mut self,
214	        source: &dynamo_llm::first_token::FirstTokenSource,
215	        dp_rank: Option<u32>,
216	    ) {
217	        let Some(dp_rank) = dp_rank else {
218	            return;
219	        };
220	        if let Some(notifier) = &self.first_token {
221	            let _ = notifier.attach_completion(source, self.inner.id(), dp_rank);
222	            return;
223	        }
224	        self.first_token =
225	            FirstTokenNotifier::for_request(None, Some(source), self.inner.id(), Some(dp_rank));
226	    }
227	
228	    /// Build the `traceparent` header value. Prefers the engine.generate
229	    /// OTel span context when valid so downstream engine spans nest under
230	    /// `engine.generate`; falls back to the inbound trace context.
231	    fn format_traceparent(&self) -> Option<String> {
232	        self.bridged_traceparent()
233	            .or_else(|| self.fallback_traceparent())
234	    }
235	
236	    fn bridged_traceparent(&self) -> Option<String> {
237	        let span = self.span.as_ref()?;
238	        let otel_ctx = span.context();
239	        let otel_span = otel_ctx.span();
240	        let sc = otel_span.span_context();
241	        if !sc.is_valid() {
242	            return None;
243	        }
244	        let flags = if sc.trace_flags().is_sampled() {
245	            "01"
246	        } else {
247	            "00"
248	        };
249	        Some(format!("00-{}-{}-{}", sc.trace_id(), sc.span_id(), flags))
250	    }
251	
252	    fn fallback_traceparent(&self) -> Option<String> {
253	        let tc = self.trace_context.as_ref()?;
254	        if tc.trace_id.is_empty() || tc.span_id.is_empty() {
255	            return None;
256	        }
257	        Some(tc.create_traceparent())
258	    }
259	}
