261	#[pymethods]
262	impl Context {
263	    #[new]
264	    #[pyo3(signature = (id=None, metadata=None))]
265	    fn py_new(id: Option<String>, metadata: Option<BTreeMap<String, String>>) -> Self {
266	        let controller = match id {
267	            Some(id) => Controller::new(id),
268	            None => Controller::default(),
269	        };
270	        Self {
271	            inner: Arc::new(controller),
272	            trace_context: None,
273	            first_token: None,
274	            metadata: Arc::new(Mutex::new(metadata.unwrap_or_default())),
275	            span: None,
276	        }
277	    }
278	
279	    /// Create a context with a fresh cancellation controller and request id.
280	    ///
281	    /// The detached context keeps the trace context, captured span, and a
282	    /// snapshot of metadata so disaggregated handoffs keep observability
283	    /// parentage without sharing cancellation ownership. The first-token
284	    /// signal is intentionally dropped.
285	    #[pyo3(signature = (id))]
286	    fn detached(&self, id: String) -> Self {
287	        Self {
288	            inner: Arc::new(Controller::new(id)),
289	            trace_context: self.trace_context.clone(),
290	            first_token: None,
291	            metadata: Arc::new(Mutex::new(self.metadata_snapshot())),
292	            span: self.span.clone(),
293	        }
294	    }
295	
296	    fn is_stopped(&self) -> bool {
297	        self.inner.is_stopped()
298	    }
299	
300	    fn is_killed(&self) -> bool {
301	        self.inner.is_killed()
302	    }
303	
304	    fn stop_generating(&self) {
305	        self.inner.stop_generating();
306	    }
307	
308	    fn id(&self) -> &str {
309	        self.inner.id()
310	    }
311	
312	    fn async_killed_or_stopped<'a>(&self, py: Python<'a>) -> PyResult<Bound<'a, PyAny>> {
313	        let inner = self.inner.clone();
314	
315	        pyo3_async_runtimes::tokio::future_into_py(py, async move {
316	            tokio::select! {
317	                _ = inner.killed() => {
318	                    Ok(true)
319	                }
320	                _ = inner.stopped() => {
321	                    Ok(true)
322	                }
323	            }
324	        })
325	    }
