327	    /// Fire the shared first-token notifier. This releases deferred decode abort and publishes
328	    /// worker-side prefill completion when configured. The framework normally auto-fires it on
329	    /// the first non-empty response chunk.
330	    fn notify_first_token(&self) {
331	        if let Some(notifier) = &self.first_token {
332	            notifier.notify();
333	        }
334	    }
