351	    #[getter]
352	    fn trace_id(&self) -> Option<String> {
353	        self.trace_context.as_ref().map(|ctx| ctx.trace_id.clone())
354	    }
355	
356	    #[getter]
357	    fn span_id(&self) -> Option<String> {
358	        self.trace_context.as_ref().map(|ctx| ctx.span_id.clone())
359	    }
360	
361	    #[getter]
362	    fn parent_span_id(&self) -> Option<String> {
363	        self.trace_context
364	            .as_ref()
365	            .and_then(|ctx| ctx.parent_id.clone())
366	    }
367	
368	    /// Handle on the framework's `engine.generate` span — the parent span
369	    /// that engine attributes / events should attach to. Always returns a
370	    /// `SpanProxy`; when no parent was plumbed in (test contexts) or the
371	    /// OTel bridge isn't installed, the proxy is a silent no-op.
372	    ///
373	    /// Prefer the `dynamo.common.backend.telemetry.current_span(context)`
374	    /// facade in engine code — it's the documented surface.
375	    fn current_span(&self) -> SpanProxy {
376	        match &self.span {
377	            Some(span) if span.context().span().span_context().is_valid() => SpanProxy {
378	                inner: SpanProxyInner::Tracing(span.clone()),
379	            },
380	            Some(_) => {
381	                warn_bridge_missing_once("current_span");
382	                SpanProxy {
383	                    inner: SpanProxyInner::NoOp,
384	                }
385	            }
386	            None => SpanProxy {
387	                inner: SpanProxyInner::NoOp,
388	            },
389	        }
390	    }
391	
392	    /// Open a child span under the `engine.generate` parent. Use this for
393	    /// dynamic span names (`tracing::info_span!` requires compile-time
394	    /// names). Returned `SpanProxy` is a context manager; the span ends on
395	    /// `__exit__` / `close()` / drop.
396	    ///
397	    /// Returns a no-op proxy when no parent was plumbed in or the bridge
398	    /// isn't installed. Prefer the
399	    /// `dynamo.common.backend.telemetry.start_span(context, name)` facade
400	    /// in engine code.
401	    #[pyo3(signature = (name, attrs=None))]
402	    fn start_span(&self, name: &str, attrs: Option<&Bound<'_, PyDict>>) -> PyResult<SpanProxy> {
403	        let Some(parent) = &self.span else {
404	            return Ok(SpanProxy {
405	                inner: SpanProxyInner::NoOp,
406	            });
407	        };
408	        let parent_ctx = parent.context();
409	        if !parent_ctx.span().span_context().is_valid() {
410	            warn_bridge_missing_once("start_span");
411	            return Ok(SpanProxy {
412	                inner: SpanProxyInner::NoOp,
413	            });
414	        }
415	        let tracer = global::tracer("dynamo");
416	        let mut otel_attrs = Vec::new();
417	        if let Some(d) = attrs {
418	            for (k, v) in d.iter() {
419	                otel_attrs.push(KeyValue::new(k.extract::<String>()?, py_to_otel_value(&v)?));
420	            }
421	        }
422	        let mut builder = tracer.span_builder(name.to_string());
423	        if !otel_attrs.is_empty() {
424	            builder = builder.with_attributes(otel_attrs);
425	        }
426	        let span = builder.start_with_context(&tracer, &parent_ctx);
427	        Ok(SpanProxy {
428	            inner: SpanProxyInner::Otel(Some(span)),
429	        })
430	    }
431	
432	    /// Build W3C trace headers for propagating to downstream inference engines.
433	    /// Returns `None` when no trace context is available (neither a captured
434	    /// engine.generate span nor inbound trace headers); callers should
435	    /// forward `None` as-is — inference engines treat it as "no upstream
436	    /// trace."
437	    ///
438	    /// Prefers the OTel context of the `engine.generate` auto-span when the
439	    /// bridge is installed, so downstream engine internals (vLLM scheduler,
440	    /// TRT-LLM forward, SGLang KV transfer) nest UNDER `engine.generate`.
441	    /// Falls back to the inbound `DistributedTraceContext` for legacy
442	    /// callers, Python-instantiated test contexts, and deployments without
443	    /// the bridge.
444	    ///
445	    /// Always emits `traceparent`. Also emits `tracestate`, `x-request-id`,
446	    /// and `request-id` when the upstream propagated them.
447	    fn trace_headers(&self) -> Option<HashMap<String, String>> {
448	        let mut headers = HashMap::new();
449	        headers.insert("traceparent".to_string(), self.format_traceparent()?);
450	        if let Some(tc) = self.trace_context.as_ref() {
451	            if let Some(ts) = &tc.tracestate {
452	                headers.insert("tracestate".to_string(), ts.clone());
453	            }
454	            if let Some(id) = &tc.x_request_id {
455	                headers.insert("x-request-id".to_string(), id.clone());
456	            }
457	            if let Some(id) = &tc.request_id {
458	                headers.insert("request-id".to_string(), id.clone());
459	            }
460	        }
461	        Some(headers)
462	    }
463	}
464	
465	/// Unified Python-facing span handle. Returned from both
466	/// `Context.current_span()` (auto-span) and `Context.start_span()` (child
467	/// span). Routes `set_attribute` / `add_event` / `set_status` to whichever
468	/// underlying span the proxy wraps.
469	///
470	/// `__enter__` / `__exit__` make the proxy usable as a `with`-block context
471	/// manager. For child spans, `__exit__` (and `close()`) ends the span; for
472	/// the auto-span the proxy is a borrow and `close()` is a no-op (the
473	/// framework owns the span's lifecycle).
474	#[pyclass]
475	pub struct SpanProxy {
476	    inner: SpanProxyInner,
477	}
478	
479	enum SpanProxyInner {
480	    /// Auto-span — borrows the `engine.generate` span via tracing. Writes
481	    /// go through `OpenTelemetrySpanExt` so attribute names are dynamic
482	    /// (no pre-declaration constraint).
483	    Tracing(tracing::Span),
484	    /// Child span — owns an OTel `BoxedSpan`. Ends on close / drop.
485	    /// `Option` makes close idempotent.
486	    Otel(Option<BoxedSpan>),
487	    /// No parent or bridge missing. All calls are silent no-ops.
488	    NoOp,
489	}
490	
491	#[pymethods]
492	impl SpanProxy {
493	    /// Set an attribute. OTel imposes no pre-declaration constraint;
494	    /// any key is accepted. No-op when the proxy is no-op or already closed.
495	    fn set_attribute(&mut self, key: &str, value: Bound<'_, PyAny>) -> PyResult<()> {
496	        match &mut self.inner {
497	            SpanProxyInner::Tracing(span) => {
498	                span.set_attribute(key.to_string(), py_to_otel_value(&value)?);
499	            }
500	            SpanProxyInner::Otel(Some(span)) => {
501	                span.set_attribute(KeyValue::new(key.to_string(), py_to_otel_value(&value)?));
502	            }
503	            _ => {}
504	        }
505	        Ok(())
506	    }
507	
508	    /// Emit a structured event. Per-attr key/value (real OTel `SpanEvent`
509	    /// fields — trace backends can query individual keys).
510	    #[pyo3(signature = (name, attrs=None))]
511	    fn add_event(&mut self, name: &str, attrs: Option<&Bound<'_, PyDict>>) -> PyResult<()> {
512	        let collect = |d: Option<&Bound<'_, PyDict>>| -> PyResult<Vec<KeyValue>> {
513	            let mut out = Vec::new();
514	            if let Some(d) = d {
515	                for (k, v) in d.iter() {
516	                    out.push(KeyValue::new(k.extract::<String>()?, py_to_otel_value(&v)?));
517	                }
518	            }
519	            Ok(out)
520	        };
521	        match &mut self.inner {
522	            SpanProxyInner::Tracing(span) => {
523	                span.add_event(name.to_string(), collect(attrs)?);
524	            }
525	            SpanProxyInner::Otel(Some(span)) => {
526	                span.add_event(name.to_string(), collect(attrs)?);
527	            }
528	            _ => {}
529	        }
530	        Ok(())
531	    }
532	
533	    /// Set the span's status. `status` is either `"ok"` or `"error"`;
534	    /// `description` is optional context (typically a short error name).
535	    #[pyo3(signature = (status, description=None))]
536	    fn set_status(&mut self, status: &str, description: Option<String>) -> PyResult<()> {
537	        let otel_status = match status {
538	            "ok" => Status::Ok,
539	            "error" => Status::error(description.unwrap_or_default()),
540	            other => {
541	                return Err(pyo3::exceptions::PyValueError::new_err(format!(
542	                    "set_status: expected \"ok\" or \"error\", got {other:?}"
543	                )));
544	            }
545	        };
546	        match &mut self.inner {
547	            SpanProxyInner::Tracing(span) => {
548	                span.set_status(otel_status);
549	            }
550	            SpanProxyInner::Otel(Some(span)) => {
551	                span.set_status(otel_status);
552	            }
553	            _ => {}
554	        }
555	        Ok(())
556	    }
557	
558	    /// End the underlying span (child spans only). Idempotent; no-op for
559	    /// the auto-span and no-op proxies. Called automatically by `__exit__`
560	    /// and on drop.
561	    fn close(&mut self) {
562	        if let SpanProxyInner::Otel(slot) = &mut self.inner
563	            && let Some(mut span) = slot.take()
564	        {
565	            span.end();
566	        }
567	    }
568	
569	    fn __enter__(slf: PyRefMut<Self>) -> PyRefMut<Self> {
570	        slf
571	    }
572	
573	    #[pyo3(signature = (_exc_type=None, _exc_value=None, _traceback=None))]
574	    fn __exit__(
575	        &mut self,
576	        _exc_type: Option<Bound<'_, PyAny>>,
577	        _exc_value: Option<Bound<'_, PyAny>>,
578	        _traceback: Option<Bound<'_, PyAny>>,
579	    ) -> bool {
580	        self.close();
581	        false
582	    }
583	}
584	
585	impl Drop for SpanProxy {
586	    fn drop(&mut self) {
587	        self.close();
588	    }
589	}
590	
591	/// Coerce a Python value into an OTel `Value` for `KeyValue` attributes.
592	/// Primitive types preserve type; everything else renders via `repr()`.
593	fn py_to_otel_value(v: &Bound<'_, PyAny>) -> PyResult<opentelemetry::Value> {
594	    use opentelemetry::Value;
595	    if let Ok(b) = v.downcast::<PyBool>() {
596	        Ok(Value::Bool(b.is_true()))
597	    } else if let Ok(i) = v.downcast::<PyInt>() {
598	        Ok(Value::I64(i.extract::<i64>()?))
599	    } else if let Ok(f) = v.downcast::<PyFloat>() {
600	        Ok(Value::F64(f.extract::<f64>()?))
601	    } else if let Ok(s) = v.downcast::<PyString>() {
602	        // `to_cow` (not `to_str`) for abi3 compatibility: enabling the
603	        // `aic-forward-pass` feature pulls in aiconfigurator-core, which sets
604	        // pyo3 `abi3-py39`; under the <3.10 limited API `PyString::to_str` is
605	        // compiled out, while `to_cow` is always available. Same conversion.
606	        Ok(Value::String(s.to_cow()?.into_owned().into()))
607	    } else {
608	        Ok(Value::String(v.repr()?.extract::<String>()?.into()))
609	    }
610	}
611	
612	// PyO3 equivalent for verify if signature contains target_name
613	// def callable_accepts_kwarg(target_name: str):
614	//      import inspect
615	//      return target_name in inspect.signature(func).parameters
616	pub fn callable_accepts_kwarg(
617	    py: Python,
618	    callable: &Bound<'_, PyAny>,
619	    target_name: &str,
620	) -> PyResult<bool> {
621	    let inspect: Bound<'_, PyModule> = py.import("inspect")?;
622	    let signature = inspect.call_method1("signature", (callable,))?;
623	    let params_any: Bound<'_, PyAny> = signature.getattr("parameters")?;
624	    params_any
625	        .call_method1("__contains__", (target_name,))?
626	        .extract::<bool>()
627	}
